-- M4.7.2: Staff invitation records.
--
-- Invitations are organization-scoped, optionally branch-scoped, single-use,
-- and stored as SHA-256 token hashes. Raw tokens are generated by the
-- `staff-invite` Edge Function and never persisted.
--
-- This migration is additive. It does not modify existing staff, role, or
-- branch assignment tables, and it does not weaken any existing constraint.

create type public.staff_invitation_status as enum (
  'pending',
  'accepted',
  'revoked',
  'expired'
);

create table public.staff_invitations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null
    references public.organizations (id) on delete restrict,
  branch_id uuid,
  email text not null,
  display_name text not null,
  role_code text not null
    references public.organization_roles (code) on delete restrict,
  scope_type public.role_scope not null,
  token_hash bytea not null,
  status public.staff_invitation_status not null default 'pending',
  invited_by_staff_id uuid not null,
  expires_at timestamptz not null,
  last_sent_at timestamptz,
  send_count integer not null default 1,
  accepted_at timestamptz,
  accepted_by_staff_id uuid,
  revoked_at timestamptz,
  revoked_by_staff_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint staff_invitations_branch_organization_fkey
    foreign key (branch_id, organization_id)
    references public.branches (id, organization_id)
    on delete restrict,
  constraint staff_invitations_invited_by_organization_fkey
    foreign key (invited_by_staff_id, organization_id)
    references public.staff_profiles (id, organization_id)
    on delete restrict,
  constraint staff_invitations_accepted_by_organization_fkey
    foreign key (accepted_by_staff_id, organization_id)
    references public.staff_profiles (id, organization_id)
    on delete restrict,
  constraint staff_invitations_revoked_by_organization_fkey
    foreign key (revoked_by_staff_id, organization_id)
    references public.staff_profiles (id, organization_id)
    on delete restrict,
  constraint staff_invitations_email_normalized_check
    check (
      email = lower(btrim(email))
      and length(email) between 3 and 320
      and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    ),
  constraint staff_invitations_display_name_check
    check (length(btrim(display_name)) between 1 and 120),
  constraint staff_invitations_role_check
    check (role_code in ('admin', 'manager', 'cashier', 'kitchen_staff')),
  constraint staff_invitations_scope_check
    check (
      (scope_type = 'organization' and branch_id is null and role_code = 'admin')
      or (scope_type = 'branch' and branch_id is not null)
    ),
  constraint staff_invitations_token_hash_check
    check (octet_length(token_hash) = 32),
  constraint staff_invitations_expiry_check
    check (expires_at > created_at),
  constraint staff_invitations_send_count_check
    check (send_count >= 1),
  constraint staff_invitations_status_state_check
    check (
      (status = 'pending'
        and accepted_at is null
        and accepted_by_staff_id is null
        and revoked_at is null
        and revoked_by_staff_id is null)
      or (status = 'accepted'
        and accepted_at is not null
        and accepted_by_staff_id is not null
        and revoked_at is null)
      or (status = 'revoked'
        and revoked_at is not null
        and accepted_at is null)
      or (status = 'expired'
        and accepted_at is null
        and accepted_by_staff_id is null
        and revoked_at is null)
    )
);

create unique index staff_invitations_token_hash_key
  on public.staff_invitations (token_hash);

-- At most one pending invitation per organization and email. Expired pending
-- rows are marked expired by the RPC before a new invitation is inserted.
create unique index staff_invitations_one_pending_per_email
  on public.staff_invitations (organization_id, email)
  where status = 'pending';

create index staff_invitations_organization_status_created_idx
  on public.staff_invitations (organization_id, status, created_at desc);

create index staff_invitations_email_idx
  on public.staff_invitations (email);

create trigger staff_invitations_set_updated_at
  before update on public.staff_invitations
  for each row execute function private.set_updated_at();

alter table public.staff_invitations enable row level security;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on public.staff_invitations from anon';
  end if;

  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on public.staff_invitations from authenticated';
  end if;
end
$$;

comment on table public.staff_invitations is
  'Single-use staff invitations. Raw tokens are never stored; only SHA-256 hashes are persisted. Access is exclusively through reviewed RPCs.';
comment on column public.staff_invitations.token_hash is
  'SHA-256 digest of the raw acceptance token generated by the staff-invite Edge Function.';
comment on column public.staff_invitations.status is
  'pending -> accepted | revoked | expired. Expiry is evaluated lazily by the invitation RPCs.';
comment on constraint staff_invitations_scope_check on public.staff_invitations is
  'Admin may be organization- or branch-scoped; Manager, Cashier, and Kitchen Staff are branch-scoped only.';
